"""Build structured A2A task status messages from Rasa tracker state (T8)."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Optional, Set

from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import Message, Part, TaskState

from rasa.core.a2a_server.proto_convert import data_part, text_part
from rasa.core.a2a_server.task_state_mapper import (
    TaskStateMappingResult,
    logical_task_state_name,
)
from rasa.dialogue_understanding.patterns.cannot_handle import (
    FLOW_PATTERN_CANNOT_HANDLE,
)
from rasa.dialogue_understanding.stack.utils import get_collect_steps_for_active_flow
from rasa.shared.constants import ROUTE_TO_CALM_SLOT
from rasa.shared.core.constants import LANGUAGE_SLOT, SLOTS_EXCLUDED_FOR_AGENT
from rasa.shared.core.events import FlowCompleted, FlowStarted

if TYPE_CHECKING:
    from rasa.shared.core.flows import FlowsList
    from rasa.shared.core.trackers import DialogueStateTracker

_EXCLUDED_PERSISTED_SLOTS = frozenset(
    SLOTS_EXCLUDED_FOR_AGENT | {ROUTE_TO_CALM_SLOT, LANGUAGE_SLOT}
)


def build_final_status_message(
    mapping: TaskStateMappingResult,
    tracker: "DialogueStateTracker",
    updater: TaskUpdater,
    *,
    flows: Optional["FlowsList"] = None,
    user_visible_text: str | None = None,
    conversation_repair_agent_utterances: list[str] | None = None,
) -> Message | None:
    """Build the message for a terminal or interactive-terminal event.

    When ``user_visible_text`` is set, a text ``Part`` is included before the
    structured data ``Part`` so clients that only read ``status.message`` still
    receive the bot utterance. Working updates during the turn remain unchanged.

    When ``conversation_repair_agent_utterances`` is set, those texts are
    included only in the structured data ``Part`` so orchestrators can decide
    whether to show them to end users
    (used when ``include_conversation_repair`` is disabled).
    """
    if mapping.state not in {
        TaskState.TASK_STATE_COMPLETED,
        TaskState.TASK_STATE_INPUT_REQUIRED,
        TaskState.TASK_STATE_REJECTED,
        TaskState.TASK_STATE_FAILED,
        TaskState.TASK_STATE_CANCELED,
        TaskState.TASK_STATE_AUTH_REQUIRED,
    }:
        return None

    data = _build_payload_data(
        mapping,
        tracker,
        flows=flows,
        conversation_repair_agent_utterances=conversation_repair_agent_utterances,
    )
    parts: list[Part] = []
    if user_visible_text and user_visible_text.strip():
        parts.append(text_part(user_visible_text.strip()))
    parts.append(data_part(data))
    return updater.new_agent_message(parts)


def _build_payload_data(
    mapping: TaskStateMappingResult,
    tracker: "DialogueStateTracker",
    *,
    flows: Optional["FlowsList"],
    conversation_repair_agent_utterances: list[str] | None = None,
) -> dict[str, Any]:
    data: dict[str, Any] = {"state": logical_task_state_name(mapping.state)}

    if conversation_repair_agent_utterances:
        data["conversation_repair_agent_utterances"] = (
            conversation_repair_agent_utterances
        )

    if mapping.state == TaskState.TASK_STATE_INPUT_REQUIRED:
        slot_names, active_flow = _active_flow_slot_names(tracker, flows)
        data["active_flow"] = active_flow
        data["slots"] = _slot_values_for_names(tracker, slot_names, include_unset=True)
        cannot_handle_reason = _cannot_handle_reason_from_last_turn(tracker)
        if cannot_handle_reason is not None:
            data["reason"] = cannot_handle_reason
        return data

    if mapping.state == TaskState.TASK_STATE_COMPLETED:
        data["slots"] = _persisted_slot_values(tracker)
        return data

    if mapping.state == TaskState.TASK_STATE_REJECTED:
        if mapping.reason is not None:
            data["reason"] = mapping.reason
        return data

    if mapping.state == TaskState.TASK_STATE_FAILED:
        data.update(_failed_payload_fields(mapping))
        return data

    if mapping.state == TaskState.TASK_STATE_CANCELED:
        data.update(_canceled_payload_fields(mapping))
        return data

    return data


def _failed_payload_fields(mapping: TaskStateMappingResult) -> dict[str, Any]:
    fields: dict[str, Any] = {}
    if mapping.error_type is not None:
        fields["error_type"] = mapping.error_type
    if mapping.error_info is not None:
        fields["error_info"] = mapping.error_info
    return fields


def _canceled_payload_fields(mapping: TaskStateMappingResult) -> dict[str, Any]:
    fields: dict[str, Any] = {}
    if mapping.canceled_name is not None:
        fields["canceled_name"] = mapping.canceled_name
    if mapping.canceled_frames is not None:
        fields["canceled_frames"] = mapping.canceled_frames
    return fields


def _active_flow_slot_names(
    tracker: "DialogueStateTracker",
    flows: Optional["FlowsList"],
) -> tuple[Set[str], Optional[str]]:
    if flows is None:
        return set(), None
    collect_steps, active_flow_id = get_collect_steps_for_active_flow(
        tracker.stack, flows
    )
    slot_names = {step.collect for step in collect_steps}
    return slot_names, active_flow_id


def _slot_values_for_names(
    tracker: "DialogueStateTracker",
    slot_names: Set[str],
    *,
    include_unset: bool = False,
) -> dict[str, Any]:
    values: dict[str, Any] = {}
    for slot_name in sorted(slot_names):
        slot_value = tracker.get_slot(slot_name)
        if include_unset or slot_value is not None:
            values[slot_name] = slot_value
    return values


def _persisted_slot_values(tracker: "DialogueStateTracker") -> dict[str, Any]:
    values: dict[str, Any] = {}
    for slot_name, slot_value in tracker.current_slot_values().items():
        if slot_name in _EXCLUDED_PERSISTED_SLOTS:
            continue
        if slot_value is not None:
            values[slot_name] = slot_value
    return values


def _cannot_handle_reason_from_last_turn(
    tracker: "DialogueStateTracker",
) -> Optional[str]:
    """Return cannot-handle ``reason`` when ``pattern_cannot_handle``
    finished this turn.

    After the repair pattern runs, the stack frame is gone but ``FlowStarted`` /
    ``FlowCompleted`` events for ``pattern_cannot_handle`` remain on the tracker.
    """
    pattern_completed = False
    reason: Optional[str] = None

    for event in tracker.get_last_turn_events():
        if (
            isinstance(event, FlowCompleted)
            and event.flow_id == FLOW_PATTERN_CANNOT_HANDLE
        ):
            pattern_completed = True
        elif (
            isinstance(event, FlowStarted)
            and event.flow_id == FLOW_PATTERN_CANNOT_HANDLE
        ):
            candidate = (event.metadata or {}).get("reason")
            if isinstance(candidate, str) and candidate:
                reason = candidate

    return reason if pattern_completed else None
